public sealed class FinanceiroSequencialRepository : BaseRepository, IFinanceiroSequencialService
{
    private readonly DapperContext _context; public FinanceiroSequencialRepository(DapperContext context) => _context = context;
    public async Task<string> ProximoAsync(long tenantId, long entidadeId, long exercicioId, int ano, string escopo, string prefixo, CancellationToken ct)
    { const string sql = "insert into sigov.financeiro_sequencial (tenant_id,entidade_id,exercicio_id,ano,escopo,ultimo_numero) values (@TenantId,@EntidadeId,@ExercicioId,@Ano,@Escopo,1) on conflict (tenant_id,entidade_id,exercicio_id,ano,escopo) do update set ultimo_numero=sigov.financeiro_sequencial.ultimo_numero+1, updated_at=now() returning ultimo_numero;"; using var cn = _context.CreateConnection(); var n = await cn.ExecuteScalarAsync<int>(Command(sql, new { TenantId = tenantId, EntidadeId = entidadeId, ExercicioId = exercicioId, Ano = ano, Escopo = escopo }, ct)).ConfigureAwait(false); return $"{prefixo}-{ano}-{n:000000}"; }
}

public sealed class OrcamentoRepository : BaseRepository, IOrcamentoRepository
{
    private readonly DapperContext _context; public OrcamentoRepository(DapperContext c) => _context = c;
    public async Task<PagedResult<OrcamentoDespesaResponse>> ListarDespesasAsync(long t,long e,long x,OrcamentoDespesaFiltro f,CancellationToken ct){var page=Math.Max(1,f.Page);var size=Math.Clamp(f.PageSize,1,100);const string select="id,orgao_unidade_orcamentaria_id as OrgaoUnidadeOrcamentariaId,programa_id as ProgramaId,acao_id as AcaoId,natureza_despesa_id as NaturezaDespesaId,fonte_recurso_id as FonteRecursoId,dotacao_inicial as DotacaoInicial,suplementacoes,reducoes,reservado,empenhado,liquidado,pago,(dotacao_inicial+suplementacoes-reducoes-reservado-empenhado) as SaldoDisponivel,ativo";var sql=$"select {select} from sigov.orcamento_despesa where tenant_id=@t and entidade_id=@e and exercicio_id=@x and is_deleted=false order by id desc limit @size offset @offset; select count(1) from sigov.orcamento_despesa where tenant_id=@t and entidade_id=@e and exercicio_id=@x and is_deleted=false;"; using var cn=_context.CreateConnection(); using var g=await cn.QueryMultipleAsync(Command(sql,new{t,e,x,size,offset=(page-1)*size},ct)).ConfigureAwait(false); return new PagedResult<OrcamentoDespesaResponse>((await g.ReadAsync<OrcamentoDespesaResponse>().ConfigureAwait(false)).AsList(),page,size,await g.ReadSingleAsync<long>().ConfigureAwait(false));}
    public async Task<OrcamentoDespesaResponse?> ObterDespesaAsync(long t,long e,long x,long id,CancellationToken ct){const string sql="select id,orgao_unidade_orcamentaria_id as OrgaoUnidadeOrcamentariaId,programa_id as ProgramaId,acao_id as AcaoId,natureza_despesa_id as NaturezaDespesaId,fonte_recurso_id as FonteRecursoId,dotacao_inicial as DotacaoInicial,suplementacoes,reducoes,reservado,empenhado,liquidado,pago,(dotacao_inicial+suplementacoes-reducoes-reservado-empenhado) as SaldoDisponivel,ativo from sigov.orcamento_despesa where tenant_id=@t and entidade_id=@e and exercicio_id=@x and id=@id and is_deleted=false;"; using var cn=_context.CreateConnection(); return await cn.QuerySingleOrDefaultAsync<OrcamentoDespesaResponse>(Command(sql,new{t,e,x,id},ct)).ConfigureAwait(false);}
    public async Task<long> CriarDespesaAsync(long t,long e,long x,OrcamentoDespesaCreateRequest r,long? u,CancellationToken ct){const string sql="insert into sigov.orcamento_despesa (tenant_id,entidade_id,exercicio_id,orgao_unidade_orcamentaria_id,programa_id,acao_id,natureza_despesa_id,fonte_recurso_id,dotacao_inicial,created_by) values (@t,@e,@x,@OrgaoUnidadeOrcamentariaId,@ProgramaId,@AcaoId,@NaturezaDespesaId,@FonteRecursoId,@DotacaoInicial,@u) returning id;"; using var cn=_context.CreateConnection(); return await cn.ExecuteScalarAsync<long>(Command(sql,new{t,e,x,r.OrgaoUnidadeOrcamentariaId,r.ProgramaId,r.AcaoId,r.NaturezaDespesaId,r.FonteRecursoId,r.DotacaoInicial,u},ct)).ConfigureAwait(false);}
    public async Task AtualizarDespesaAsync(long t,long e,long x,long id,OrcamentoDespesaUpdateRequest r,long? u,CancellationToken ct){const string sql="update sigov.orcamento_despesa set orgao_unidade_orcamentaria_id=@OrgaoUnidadeOrcamentariaId,programa_id=@ProgramaId,acao_id=@AcaoId,natureza_despesa_id=@NaturezaDespesaId,fonte_recurso_id=@FonteRecursoId,dotacao_inicial=@DotacaoInicial,ativo=@Ativo,updated_at=now(),updated_by=@u where tenant_id=@t and entidade_id=@e and exercicio_id=@x and id=@id and is_deleted=false;"; using var cn=_context.CreateConnection(); await cn.ExecuteAsync(Command(sql,new{t,e,x,id,r.OrgaoUnidadeOrcamentariaId,r.ProgramaId,r.AcaoId,r.NaturezaDespesaId,r.FonteRecursoId,r.DotacaoInicial,r.Ativo,u},ct)).ConfigureAwait(false);}
    public async Task MovimentarDespesaAsync(long t,long e,long x,long id,MovimentacaoOrcamentariaRequest r,long? u,CancellationToken ct){var col=r.TipoMovimentacao.Equals("REDUCAO",StringComparison.OrdinalIgnoreCase)?"reducoes":"suplementacoes";var sql=$"update sigov.orcamento_despesa set {col}={col}+@Valor,updated_at=now(),updated_by=@u where tenant_id=@t and entidade_id=@e and exercicio_id=@x and id=@id and is_deleted=false; insert into sigov.orcamento_movimentacao (tenant_id,entidade_id,exercicio_id,orcamento_despesa_id,tipo_movimentacao,valor,historico,created_by) values (@t,@e,@x,@id,@TipoMovimentacao,@Valor,@Historico,@u);"; using var cn=_context.CreateConnection(); await cn.ExecuteAsync(Command(sql,new{t,e,x,id,r.TipoMovimentacao,r.Valor,r.Historico,u},ct)).ConfigureAwait(false);}
    public async Task<PagedResult<OrcamentoReceitaResponse>> ListarReceitasAsync(long t,long e,long x,OrcamentoReceitaFiltro f,CancellationToken ct){var page=Math.Max(1,f.Page);var size=Math.Clamp(f.PageSize,1,100);const string sql="select id,natureza_receita_id as NaturezaReceitaId,fonte_recurso_id as FonteRecursoId,previsao_inicial as PrevisaoInicial,previsao_atualizada as PrevisaoAtualizada,lancado,arrecadado,ativo from sigov.orcamento_receita where tenant_id=@t and entidade_id=@e and exercicio_id=@x and is_deleted=false order by id desc limit @size offset @offset; select count(1) from sigov.orcamento_receita where tenant_id=@t and entidade_id=@e and exercicio_id=@x and is_deleted=false;"; using var cn=_context.CreateConnection(); using var g=await cn.QueryMultipleAsync(Command(sql,new{t,e,x,size,offset=(page-1)*size},ct)).ConfigureAwait(false); return new PagedResult<OrcamentoReceitaResponse>((await g.ReadAsync<OrcamentoReceitaResponse>().ConfigureAwait(false)).AsList(),page,size,await g.ReadSingleAsync<long>().ConfigureAwait(false));}
    public async Task<OrcamentoReceitaResponse?> ObterReceitaAsync(long t,long e,long x,long id,CancellationToken ct){const string sql="select id,natureza_receita_id as NaturezaReceitaId,fonte_recurso_id as FonteRecursoId,previsao_inicial as PrevisaoInicial,previsao_atualizada as PrevisaoAtualizada,lancado,arrecadado,ativo from sigov.orcamento_receita where tenant_id=@t and entidade_id=@e and exercicio_id=@x and id=@id and is_deleted=false;"; using var cn=_context.CreateConnection(); return await cn.QuerySingleOrDefaultAsync<OrcamentoReceitaResponse>(Command(sql,new{t,e,x,id},ct)).ConfigureAwait(false);}
    public async Task<long> CriarReceitaAsync(long t,long e,long x,OrcamentoReceitaCreateRequest r,long? u,CancellationToken ct){const string sql="insert into sigov.orcamento_receita (tenant_id,entidade_id,exercicio_id,natureza_receita_id,fonte_recurso_id,previsao_inicial,previsao_atualizada,created_by) values (@t,@e,@x,@NaturezaReceitaId,@FonteRecursoId,@PrevisaoInicial,@PrevisaoInicial,@u) returning id;"; using var cn=_context.CreateConnection(); return await cn.ExecuteScalarAsync<long>(Command(sql,new{t,e,x,r.NaturezaReceitaId,r.FonteRecursoId,r.PrevisaoInicial,u},ct)).ConfigureAwait(false);}
    public async Task AtualizarReceitaAsync(long t,long e,long x,long id,OrcamentoReceitaUpdateRequest r,long? u,CancellationToken ct){const string sql="update sigov.orcamento_receita set natureza_receita_id=@NaturezaReceitaId,fonte_recurso_id=@FonteRecursoId,previsao_inicial=@PrevisaoInicial,previsao_atualizada=@PrevisaoAtualizada,ativo=@Ativo,updated_at=now(),updated_by=@u where tenant_id=@t and entidade_id=@e and exercicio_id=@x and id=@id and is_deleted=false;"; using var cn=_context.CreateConnection(); await cn.ExecuteAsync(Command(sql,new{t,e,x,id,r.NaturezaReceitaId,r.FonteRecursoId,r.PrevisaoInicial,r.PrevisaoAtualizada,r.Ativo,u},ct)).ConfigureAwait(false);}
}

public sealed class EmpenhoRepository : BaseRepository, IEmpenhoRepository
{
    private readonly DapperContext _context; public EmpenhoRepository(DapperContext c) => _context = c;
    public async Task<PagedResult<EmpenhoResumoResponse>> ListarAsync(long t,long e,long x,EmpenhoFiltro f,CancellationToken ct){var page=Math.Max(1,f.Page);var size=Math.Clamp(f.PageSize,1,100);const string sql="select emp.id, emp.numero, emp.data_empenho as DataEmpenho, coalesce(p.nome,'Fornecedor protegido') as Fornecedor, coalesce(nd.nome,'') as Natureza, coalesce(fr.nome,'') as Fonte, emp.valor_total as ValorTotal, emp.valor_liquidado as ValorLiquidado, emp.valor_pago as ValorPago, (emp.valor_total-emp.valor_anulado-emp.valor_pago) as Saldo, emp.status from sigov.empenho emp join sigov.orcamento_despesa od on od.id=emp.orcamento_despesa_id and od.tenant_id=@t left join sigov.pessoa p on p.id=emp.fornecedor_pessoa_id left join sigov.natureza_despesa nd on nd.id=od.natureza_despesa_id left join sigov.fonte_recurso fr on fr.id=od.fonte_recurso_id where emp.tenant_id=@t and emp.entidade_id=@e and emp.exercicio_id=@x and emp.is_deleted=false order by emp.id desc limit @size offset @offset; select count(1) from sigov.empenho emp where emp.tenant_id=@t and emp.entidade_id=@e and emp.exercicio_id=@x and emp.is_deleted=false;"; using var cn=_context.CreateConnection(); using var g=await cn.QueryMultipleAsync(Command(sql,new{t,e,x,size,offset=(page-1)*size},ct)).ConfigureAwait(false); return new PagedResult<EmpenhoResumoResponse>((await g.ReadAsync<EmpenhoResumoResponse>().ConfigureAwait(false)).AsList(),page,size,await g.ReadSingleAsync<long>().ConfigureAwait(false));}
    public async Task<EmpenhoDetalheResponse?> ObterAsync(long t,long e,long x,long id,CancellationToken ct){const string sql="select emp.id, emp.numero, emp.data_empenho as DataEmpenho, emp.orcamento_despesa_id as OrcamentoDespesaId, emp.fornecedor_pessoa_id as FornecedorPessoaId, coalesce(p.nome,'Fornecedor protegido') as Fornecedor, emp.historico, emp.tipo_empenho as TipoEmpenho, emp.valor_total as ValorTotal, emp.valor_anulado as ValorAnulado, emp.valor_liquidado as ValorLiquidado, emp.valor_pago as ValorPago, emp.status from sigov.empenho emp left join sigov.pessoa p on p.id=emp.fornecedor_pessoa_id where emp.tenant_id=@t and emp.entidade_id=@e and emp.exercicio_id=@x and emp.id=@id and emp.is_deleted=false; select id,descricao,quantidade,valor_unitario as ValorUnitario,valor_total as ValorTotal from sigov.empenho_item where tenant_id=@t and entidade_id=@e and exercicio_id=@x and empenho_id=@id and is_deleted=false order by id;"; using var cn=_context.CreateConnection(); using var g=await cn.QueryMultipleAsync(Command(sql,new{t,e,x,id},ct)).ConfigureAwait(false); var emp=await g.ReadSingleOrDefaultAsync<EmpenhoDetalheRow>().ConfigureAwait(false); if(emp is null)return null; var itens=(await g.ReadAsync<EmpenhoItemResponse>().ConfigureAwait(false)).AsList(); return new EmpenhoDetalheResponse(emp.Id,emp.Numero,emp.DataEmpenho,emp.OrcamentoDespesaId,emp.FornecedorPessoaId,emp.Fornecedor,emp.Historico,emp.TipoEmpenho,emp.ValorTotal,emp.ValorAnulado,emp.ValorLiquidado,emp.ValorPago,emp.Status,itens);}
    public async Task<long> CriarAsync(long t,long e,long x,string numero,int ano,EmpenhoCreateRequest r,long? u,CancellationToken ct){var valor=r.Itens.Sum(i=>decimal.Round(i.Quantidade*i.ValorUnitario,2)); const string sql="with saldo as (update sigov.orcamento_despesa set empenhado=empenhado+@valor,updated_at=now(),updated_by=@u where tenant_id=@t and entidade_id=@e and exercicio_id=@x and id=@OrcamentoDespesaId and is_deleted=false and (dotacao_inicial+suplementacoes-reducoes-reservado-empenhado)>=@valor returning id) insert into sigov.empenho (tenant_id,entidade_id,exercicio_id,orcamento_despesa_id,numero,ano,data_empenho,fornecedor_pessoa_id,historico,tipo_empenho,valor_total,status,metadados,created_by) select @t,@e,@x,@OrcamentoDespesaId,@numero,@ano,@DataEmpenho,@FornecedorPessoaId,@Historico,@TipoEmpenho,@valor,'EMITIDO',jsonb_build_object('observacoes',@Observacoes),@u from saldo returning id;"; using var cn=_context.CreateConnection(); var id=await cn.ExecuteScalarAsync<long>(Command(sql,new{t,e,x,numero,ano,r.OrcamentoDespesaId,r.DataEmpenho,r.FornecedorPessoaId,r.Historico,r.TipoEmpenho,Observacoes=r.Observacoes,valor,u},ct)).ConfigureAwait(false); foreach(var item in r.Itens){const string itemSql="insert into sigov.empenho_item (tenant_id,entidade_id,exercicio_id,empenho_id,descricao,quantidade,valor_unitario,valor_total,created_by) values (@t,@e,@x,@id,@Descricao,@Quantidade,@ValorUnitario,@ValorTotal,@u);"; await cn.ExecuteAsync(Command(itemSql,new{t,e,x,id,item.Descricao,item.Quantidade,item.ValorUnitario,ValorTotal=decimal.Round(item.Quantidade*item.ValorUnitario,2),u},ct)).ConfigureAwait(false);} await RegistrarEvento(cn,t,e,x,"EmpenhoEmitido",new{id,numero,valor},u,ct).ConfigureAwait(false); return id;}
    public async Task AtualizarAsync(long t,long e,long x,long id,EmpenhoUpdateRequest r,long? u,CancellationToken ct){const string sql="update sigov.empenho set data_empenho=@DataEmpenho,historico=@Historico,tipo_empenho=@TipoEmpenho,metadados=jsonb_build_object('observacoes',@Observacoes),updated_at=now(),updated_by=@u where tenant_id=@t and entidade_id=@e and exercicio_id=@x and id=@id and is_deleted=false and status <> 'ANULADO';"; using var cn=_context.CreateConnection(); await cn.ExecuteAsync(Command(sql,new{t,e,x,id,r.DataEmpenho,r.Historico,r.TipoEmpenho,r.Observacoes,u},ct)).ConfigureAwait(false);}
    public async Task AnularAsync(long t,long e,long x,long id,AnularEmpenhoRequest r,long? u,CancellationToken ct){const string sql="update sigov.empenho set valor_anulado=valor_anulado+@Valor,status='ANULADO',updated_at=now(),updated_by=@u where tenant_id=@t and entidade_id=@e and exercicio_id=@x and id=@id and is_deleted=false and status <> 'ANULADO' and @Valor <= (valor_total-valor_anulado-valor_liquidado); update sigov.orcamento_despesa od set empenhado=greatest(0,empenhado-@Valor),updated_at=now(),updated_by=@u from sigov.empenho emp where emp.orcamento_despesa_id=od.id and emp.id=@id and emp.tenant_id=@t and od.tenant_id=@t;"; using var cn=_context.CreateConnection(); await cn.ExecuteAsync(Command(sql,new{t,e,x,id,r.Valor,u},ct)).ConfigureAwait(false); await RegistrarEvento(cn,t,e,x,"EmpenhoAnulado",new{id,r.Valor,r.Motivo},u,ct).ConfigureAwait(false);}
    private static async Task RegistrarEvento(System.Data.IDbConnection cn,long t,long e,long x,string tipo,object payload,long? u,CancellationToken ct){const string sql="insert into sigov.fila_evento (tenant_id,entidade_id,exercicio_id,tipo_evento,payload,created_by) values (@t,@e,@x,@tipo,@payload::jsonb,@u);"; await cn.ExecuteAsync(Command(sql,new{t,e,x,tipo,payload=System.Text.Json.JsonSerializer.Serialize(payload),u},ct)).ConfigureAwait(false);}
    private sealed record EmpenhoDetalheRow(long Id,string Numero,DateOnly DataEmpenho,long OrcamentoDespesaId,long FornecedorPessoaId,string Fornecedor,string Historico,string TipoEmpenho,decimal ValorTotal,decimal ValorAnulado,decimal ValorLiquidado,decimal ValorPago,string Status);
}

