    public async Task<long> CriarAsync(long t,long e,long x,long empenhoId,string numero,LiquidacaoCreateRequest r,long? u,CancellationToken ct){const string sql="with saldo as (update sigov.empenho set valor_liquidado=valor_liquidado+@Valor,status=case when valor_total-valor_anulado-valor_liquidado-@Valor <= 0 then 'LIQUIDADO_TOTAL' else 'LIQUIDADO_PARCIAL' end,updated_at=now(),updated_by=@u where tenant_id=@t and entidade_id=@e and exercicio_id=@x and id=@empenhoId and status <> 'ANULADO' and @Valor <= (valor_total-valor_anulado-valor_liquidado) returning id) insert into sigov.liquidacao (tenant_id,entidade_id,exercicio_id,empenho_id,numero,data_liquidacao,documento_fiscal,historico,valor,status,created_by) select @t,@e,@x,@empenhoId,@numero,@DataLiquidacao,@DocumentoFiscal,@Historico,@Valor,'LIQUIDADA',@u from saldo returning id;"; using var cn=_context.CreateConnection(); var id=await cn.ExecuteScalarAsync<long>(Command(sql,new{t,e,x,empenhoId,numero,r.DataLiquidacao,r.DocumentoFiscal,r.Historico,r.Valor,u},ct)).ConfigureAwait(false); await cn.ExecuteAsync(Command("insert into sigov.fila_evento (entidade_id,exercicio_id,tipo_evento,payload,created_by) values (@e,@x,'EmpenhoLiquidado',jsonb_build_object('liquidacaoId',@id,'empenhoId',@empenhoId,'valor',@Valor),@u);",new{e,x,id,empenhoId,r.Valor,u},ct)).ConfigureAwait(false); return id;}
    public async Task AnularAsync(long t,long e,long x,long id,AnularLiquidacaoRequest r,long? u,CancellationToken ct){const string sql="update sigov.liquidacao set status='ANULADA',updated_at=now(),updated_by=@u where tenant_id=@t and entidade_id=@e and exercicio_id=@x and id=@id and status <> 'ANULADA';"; using var cn=_context.CreateConnection(); await cn.ExecuteAsync(Command(sql,new{t,e,x,id,u},ct)).ConfigureAwait(false); _=r;}
}
public sealed class PagamentoRepository : BaseRepository, IPagamentoRepository
