    public async Task<long> CriarAsync(long t,long e,long x,long liquidacaoId,string numero,PagamentoCreateRequest r,long? u,CancellationToken ct){const string sql="with liq as (select * from sigov.liquidacao where tenant_id=@t and entidade_id=@e and exercicio_id=@x and id=@liquidacaoId and status <> 'ANULADA' and @Valor <= valor), ins as (insert into sigov.pagamento (tenant_id,entidade_id,exercicio_id,liquidacao_id,numero,data_pagamento,forma_pagamento,conta_bancaria,historico,valor,status,created_by) select @t,@e,@x,@liquidacaoId,@numero,@DataPagamento,@FormaPagamento,@ContaBancaria,@Historico,@Valor,'EFETUADO',@u from liq returning id) update sigov.empenho emp set valor_pago=valor_pago+@Valor,status='PAGO_PARCIAL' from sigov.liquidacao liq where liq.empenho_id=emp.id and liq.id=@liquidacaoId and emp.tenant_id=@t returning (select id from ins);"; using var cn=_context.CreateConnection(); var id=await cn.ExecuteScalarAsync<long>(Command(sql,new{t,e,x,liquidacaoId,numero,r.DataPagamento,r.FormaPagamento,r.ContaBancaria,r.Historico,r.Valor,u},ct)).ConfigureAwait(false); await cn.ExecuteAsync(Command("insert into sigov.fila_evento (entidade_id,exercicio_id,tipo_evento,payload,created_by) values (@e,@x,'PagamentoRealizado',jsonb_build_object('pagamentoId',@id,'valor',@Valor),@u);",new{e,x,id,r.Valor,u},ct)).ConfigureAwait(false); return id;}
